contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint128 newVirtualBaseTokenReserves, uint128 newVirtualNftReserves) public {
        c.initialize(
            address(0),
            address(0),
            1,
            1,
            0,
            0,
            bytes32(0),
            false,
            false
        ); if (__ESBMC_reverted()) return;

        c.setVirtualReserves(newVirtualBaseTokenReserves, newVirtualNftReserves); if (__ESBMC_reverted()) return;

        uint128 readVirtualBaseTokenReserves = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;
        uint128 readVirtualNftReserves = c.virtualNftReserves(); if (__ESBMC_reverted()) return;

        assert(
            readVirtualBaseTokenReserves == newVirtualBaseTokenReserves &&
            readVirtualNftReserves == newVirtualNftReserves
        );
    }

    receive() external payable {}
}

