pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint128 newVirtualBaseTokenReserves, uint128 newVirtualNftReserves) internal {
        try c.initialize(
            address(0),
            address(0),
            1,
            1,
            0,
            0,
            bytes32(0),
            false,
            false
        ) {} catch { return; }
        try c.setVirtualReserves(newVirtualBaseTokenReserves, newVirtualNftReserves) {} catch { return; }
        uint128 readVirtualBaseTokenReserves;
        try c.virtualBaseTokenReserves() returns (uint128 __r) { readVirtualBaseTokenReserves = __r; } catch { return; }
        uint128 readVirtualNftReserves;
        try c.virtualNftReserves() returns (uint128 __r) { readVirtualNftReserves = __r; } catch { return; }
        assertTrue(readVirtualBaseTokenReserves == newVirtualBaseTokenReserves &&
            readVirtualNftReserves == newVirtualNftReserves);
    }

    function testFuzz_run(uint128 newVirtualBaseTokenReserves, uint128 newVirtualNftReserves) public {
        _run(newVirtualBaseTokenReserves, newVirtualNftReserves);
    }

    receive() external payable {}
}
